item.aggregated_output:
        raise OpenAIError(f"HTTP {exc.code} from {url}: {detail}") from exc
    except urllib.error.URLError as exc:
        raise OpenAIError(f"Request to {url} failed: {exc.reason}") from exc

    try:
        return json.loads(raw)
    except json.JSONDecodeError as exc:
        raise OpenAIError(f"Invalid JSON response from {url}: {raw[:200]!r}") from exc


def extract_text(response: dict) -> str:
    """Return the assistant's text from a Responses API payload.

    Prefers the convenience ``output_text`` field when present and otherwise
    walks ``output`` message items collecting ``output_text`` content blocks.
    """
    direct = response.get("output_text")
    if isinstance(direct, str):
        return direct

    chunks: list[str] = []
    for item in response.get("output", []) or []:
        if item.get("type") != "message":
            continue
        for content in item.get("content", []) or []:
            text = content.get("text")
            if isinstance(text, str):
                chunks.append(text)
    return "".join(chunks)
